<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import type { ColDef } from 'ag-grid-community'
import AppDataGrid from '@/components/AppDataGrid.vue'
import { createIOTACLRule,deleteIOTACLRule,listIOTACLRules,listIOTClients,listIOTMessages,listIOTTopics,updateIOTACLRule } from '@/api/iot'
import { getRoles, type RoleResponse } from '@/api/role'
const route=useRoute();const kind=computed(()=>String(route.meta.iotKind||'acl'));const title=computed(()=>String(route.meta.title||'IOT'))
const rows=ref<any[]>([]),roles=ref<RoleResponse[]>([]),keyword=ref(''),status=ref(''),page=ref(1),limit=ref(20),total=ref(0),loading=ref(false),dialog=ref(false),saving=ref(false),editing=ref(false)
const form=reactive<any>({id:0,role_id:0,operation:'publish',effect:'allow',topic_filter:'#'})
let timer:ReturnType<typeof setTimeout>|undefined
const editable=computed(()=>kind.value==='acl')
const placeholder=computed(()=>({acl:'搜索 Topic 过滤器',topics:'搜索 Topic',messages:'搜索 Topic、客户端、用户或内容',clients:'搜索客户端、用户或地址'} as any)[kind.value]||'搜索')
function seq(p:any){return(page.value-1)*limit.value+p.node.rowIndex+1}
function actions(p:any){const box=document.createElement('div');box.className='iot-actions';const edit=document.createElement('button');edit.textContent='编辑';edit.className='edit';edit.onclick=()=>openEdit(p.data);const del=document.createElement('button');del.textContent='删除';del.className='delete';del.onclick=()=>remove(p.data);box.append(edit,del);return box}
const columns=computed<ColDef[]>(()=>{const first={headerName:'序号',valueGetter:seq,width:62};const action={headerName:'操作',width:150,pinned:'right' as const,cellRenderer:actions};const map:any={acl:[first,{field:'role_name',headerName:'系统角色'},{field:'operation',headerName:'操作',valueFormatter:(p:any)=>p.value==='publish'?'发布':'订阅'},{field:'effect',headerName:'效果',valueFormatter:(p:any)=>p.value==='allow'?'允许':'拒绝'},{field:'topic_filter',headerName:'Topic 过滤器'},action],topics:[first,{field:'topic',headerName:'Topic'}],messages:[first,{field:'topic',headerName:'Topic'},{field:'payload',headerName:'内容',minWidth:260},{field:'client_id',headerName:'客户端'},{field:'username',headerName:'用户'},{field:'qos',headerName:'QoS'},{field:'retained',headerName:'保留',valueFormatter:(p:any)=>p.value?'是':'否'},{field:'received_at',headerName:'接收时间'}],clients:[first,{field:'client_id',headerName:'客户端'},{field:'status',headerName:'状态',valueFormatter:(p:any)=>p.value==='connected'?'已连接':'已断开'},{field:'username',headerName:'用户'},{field:'remote_address',headerName:'远端地址'},{field:'listener',headerName:'监听器'},{field:'protocol_version',headerName:'协议版本'},{field:'connected_at',headerName:'连接时间'},{field:'disconnect_reason',headerName:'断开原因'}]};return map[kind.value]||[]})
async function loadRoles(){const{data}=await getRoles(1,1000);roles.value=data.data.list}
async function load(){loading.value=true;try{const params={page:page.value,limit:limit.value,keyword:keyword.value.trim(),status:status.value};const fn:any=({acl:listIOTACLRules,topics:listIOTTopics,messages:listIOTMessages,clients:listIOTClients} as any)[kind.value];const{data}=await fn(params);rows.value=data.data.list;total.value=data.data.total;if(kind.value==='acl')await loadRoles()}finally{loading.value=false}}
function reset(){Object.assign(form,{id:0,role_id:roles.value[0]?.id||0,operation:'publish',effect:'allow',topic_filter:'#'})}
function openCreate(){editing.value=false;reset();dialog.value=true}
function openEdit(row:any){editing.value=true;reset();Object.assign(form,row);dialog.value=true}
async function save(){saving.value=true;try{await (editing.value?updateIOTACLRule:createIOTACLRule)({...form});dialog.value=false;ElMessage.success('保存成功');await load()}finally{saving.value=false}}
async function remove(row:any){await ElMessageBox.confirm('删除后不可恢复，确定继续吗？','删除确认',{type:'warning'});await deleteIOTACLRule(row.id);ElMessage.success('删除成功');await load()}
watch(keyword,()=>{if(timer)clearTimeout(timer);timer=setTimeout(()=>{page.value=1;void load()},300)});watch(kind,()=>{page.value=1;keyword.value='';status.value='';void load()},{immediate:true});onBeforeUnmount(()=>{if(timer)clearTimeout(timer)})
</script>
<template><section v-loading="loading" class="iot-page"><header><div><h1>{{title}}</h1><p>IOT MQTT {{title}}。</p></div><el-button v-if="editable" type="primary" @click="openCreate">新增</el-button></header><div class="toolbar"><el-input v-model="keyword" :placeholder="placeholder" clearable/><el-select v-if="kind==='clients'" v-model="status" placeholder="全部状态" clearable @change="page=1;load()"><el-option label="已连接" value="connected"/><el-option label="已断开" value="disconnected"/></el-select></div><AppDataGrid class="grid" :row-data="rows" :column-defs="columns" pagination server-pagination :total="total" :current-page="page" :page-size="limit" @page-change="v=>{page=v;load()}" @page-size-change="v=>{limit=v;page=1;load()}"/><el-dialog v-model="dialog" :title="editing?'编辑':'新增'" width="560px" destroy-on-close><el-form label-position="top"><el-form-item label="系统角色"><el-select v-model="form.role_id"><el-option v-for="r in roles" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><template v-if="editing"><el-form-item label="规则类型"><el-radio-group v-model="form.operation"><el-radio-button value="publish">发布</el-radio-button><el-radio-button value="subscribe">订阅</el-radio-button></el-radio-group></el-form-item><el-form-item label="效果"><el-radio-group v-model="form.effect"><el-radio-button value="allow">允许</el-radio-button><el-radio-button value="deny">拒绝</el-radio-button></el-radio-group></el-form-item><el-form-item label="Topic 过滤器"><el-input v-model="form.topic_filter" placeholder="例如 devices/+/status 或 #"/></el-form-item></template><template v-else><section class="rule-section"><el-checkbox v-model="form.publish_enabled">发布规则</el-checkbox><template v-if="form.publish_enabled"><el-form-item label="效果"><el-radio-group v-model="form.publish_effect"><el-radio-button value="allow">允许</el-radio-button><el-radio-button value="deny">拒绝</el-radio-button></el-radio-group></el-form-item><el-form-item label="Topic 过滤器"><el-input v-model="form.publish_topic_filter" placeholder="发布 Topic，例如 devices/+/status"/></el-form-item></template></section><section class="rule-section"><el-checkbox v-model="form.subscribe_enabled">订阅规则</el-checkbox><template v-if="form.subscribe_enabled"><el-form-item label="效果"><el-radio-group v-model="form.subscribe_effect"><el-radio-button value="allow">允许</el-radio-button><el-radio-button value="deny">拒绝</el-radio-button></el-radio-group></el-form-item><el-form-item label="Topic 过滤器"><el-input v-model="form.subscribe_topic_filter" placeholder="订阅 Topic，例如 devices/#"/></el-form-item></template></section></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.iot-page{height:100%;min-width:0;display:flex;flex-direction:column;gap:8px;padding:0 8px;box-sizing:border-box;font-size:11px}.iot-page header{display:flex;align-items:center;justify-content:space-between}.iot-page h1{margin:0;font-size:18px}.iot-page header p{margin:3px 0 0;color:var(--text-secondary)}.toolbar{display:flex;gap:7px}.toolbar .el-input{width:210px}.toolbar .el-select{width:115px}.grid{flex:1;min-height:0}.rule-section{padding:8px 10px 0;border:1px solid var(--line);border-radius:6px;margin-bottom:10px}.rule-section :deep(.el-form-item){margin-bottom:10px}.rule-section :deep(.el-checkbox){margin-bottom:8px}.grid :deep(.iot-actions){display:flex;align-items:center;gap:6px;height:100%}.grid :deep(.iot-actions button){padding:4px 9px;border-radius:7px;background:#fff;font-size:11px;cursor:pointer}.grid :deep(.iot-actions .edit){border:1px solid var(--primary);color:var(--primary)}.grid :deep(.iot-actions .delete){border:1px solid #f2b8b5;color:#d92d20;background:#fff7f6}</style>
